def get_headers(headers):
    """
    Get headers from the list of headers
    """
    for header in headers:
        if header['subheaders']:
            get_headers(header['subheaders'])
        else:
            yield header


def get_header_by_id(headers, header_id):
    """
    Get header by id
    """
    for header in headers:
        if header['id'] == header_id:
            return header
        if header['subheaders']:
            header = get_header_by_id(header['subheaders'], header_id)
            if header:
                return header


